std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dis(0.0, 1.0);
int intersections = 0;
for (int i = 0; i < numberOfChecks; i++) {
    double x = dis(gen);
    double y = dis(gen);
    double z = dis(gen);
    cg3::Point3d direction(x, y, z);
    direction.normalize();
    cg3::Point3d rayOrigin = p;
    cg3::Ray3d ray(rayOrigin, direction);
    int intersectionsWithMesh = tree.numberIntersectedPrimitives(rayOrigin, rayOrigin + direction * 10000);
    if (intersectionsWithMesh % 2 == 1) {
        intersections++;
    }
}
return intersections > numberOfChecks / 2;

